using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using UnscRelay.Core;
internal static class ErasureClientChecks
{
 sealed class Server:HttpMessageHandler{public int Requests;public bool WrongIntent,WrongGrace,Fail;public string State="pending";public readonly Guid Request=Guid.NewGuid();public readonly DateTimeOffset Deadline=DateTimeOffset.UtcNow.AddDays(30);public string[] Fields=>["account.delete","self","30","owned-archives-and-account-data"];protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){Requests++;if(request.RequestUri!.Scheme!="https"||request.RequestUri.Host!="unsc.responda.eu"||request.Headers.Authorization?.Parameter!="synthetic-access")throw new Exception("Invalid erasure transport");if(Fail)return new(HttpStatusCode.ServiceUnavailable){Content=JsonContent.Create(new{error="Synthetic outage"})};if(request.RequestUri.AbsolutePath.EndsWith("/review",StringComparison.Ordinal))return new(HttpStatusCode.OK){Content=JsonContent.Create(new{intent=WrongIntent?new string('0',64):CloudAccountClient.SensitiveIntentHash(Fields),fields=Fields,archives=Array.Empty<object>(),graceDays=WrongGrace?1:30})};if(request.RequestUri.AbsolutePath.EndsWith("/confirm",StringComparison.Ordinal)){var body=await request.Content!.ReadFromJsonAsync<JsonElement>(ct);if(body.GetProperty("code").GetString()!="12345678")throw new Exception("Changed mailbox code");return new(HttpStatusCode.OK){Content=JsonContent.Create(new{status=new{state=State,executeAfter=Deadline},notificationQueued=true})};}return new(HttpStatusCode.OK){Content=JsonContent.Create(new{status=new{state=State,executeAfter=Deadline},cancelFields=new[]{"account.delete.cancel","self",Request.ToString("D"),Deadline.ToString("O")}})};}}
 public static async Task<int> Run(){var directory=Directory.CreateTempSubdirectory("relay-erasure-client-");var count=0;void Check(bool value,string label){if(!value)throw new Exception(label);count++;Console.WriteLine("PASS erasure client: "+label);}try{var server=new Server();using var client=new CloudAccountClient(directory.FullName,server);try{await client.ReviewAccountDeletion(false,CancellationToken.None);throw new Exception("Disconnected review accepted");}catch(OnlineAccessException){Check(server.Requests==0,"disconnected account cannot retrieve deletion inventory");}client.State.Activated=true;client.State.AccessToken="synthetic-access";client.State.TokenExpires=DateTimeOffset.UtcNow.AddMinutes(5);var review=await client.ReviewAccountDeletion(false,CancellationToken.None);Check(review.Intent==CloudAccountClient.SensitiveIntentHash(review.Fields)&&review.GraceDays==30&&!review.Cancel,"native process verifies consent digest and full thirty-day period");foreach(var changed in new[]{"intent","grace"}){server.WrongIntent=changed=="intent";server.WrongGrace=changed=="grace";try{await client.ReviewAccountDeletion(false,CancellationToken.None);throw new Exception("Changed review accepted");}catch(InvalidDataException){Check(true,"modified "+changed+" cannot become a native confirmation");}}server.WrongGrace=server.WrongIntent=false;var cancel=await client.ReviewAccountDeletion(true,CancellationToken.None);Check(cancel.Cancel&&cancel.Fields[0]=="account.delete.cancel"&&cancel.Fields[2]==server.Request.ToString("D"),"cancellation binds its own action and exact request identity");server.State="frozen";try{await client.ReviewAccountDeletion(true,CancellationToken.None);throw new Exception("Frozen cancellation accepted");}catch(InvalidDataException){Check(true,"frozen destruction cannot be presented as cancelable");}var before=server.Requests;try{await client.ConfirmAccountDeletion(review,Guid.NewGuid(),new string('1',17),CancellationToken.None);throw new Exception("Oversized code accepted");}catch(ArgumentException){Check(server.Requests==before,"invalid email code is rejected before network");}server.Fail=true;before=server.Requests;try{await client.ConfirmAccountDeletion(review,Guid.NewGuid(),"12345678",CancellationToken.None);throw new Exception("Failed confirmation accepted");}catch(OnlineAccessException){Check(server.Requests==before+1,"uncertain destructive confirmation is not automatically retried");}Console.WriteLine("Erasure client checks: "+count);return 0;}finally{directory.Delete(true);}}
}
